const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  const num = (field, v, least) => {
    if (!UINT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
    return BigInt(v)
  }
  const declare = (name, make) => {
    if (!NAME.test(name)) throw new Fail(`invalid policy name ${name}`)
    return make
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (!['bucket', 'window', 'route', 'event'].includes(d)) throw new Fail(`unknown directive ${d}`)
      if (d !== 'event' && events.length) throw new Fail('declarations must come before the first event')
      if (d === 'bucket') {
        if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const capacity = num('capacity', t[2], 1)
        const refill = num('refill', t[3], 0)
        const per = num('per', t[4], 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
      } else if (d === 'window') {
        if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const limit = num('limit', t[2], 0)
        const span = num('span', t[3], 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'window', name: t[1], limit, span })
      } else if (d === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        for (const p of t.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
        routes.set(t[1], t.slice(2).map((p) => policies.get(p)))
      } else {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        last = tick
        events.push({ tick, key: t[2] })
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map() // policy name + key -> state
  const stateOf = (p, key, tick) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { tokens: p.capacity * p.per, at: tick } : { ticks: [] }
      states.set(id, s)
    }
    if (p.kind === 'bucket') {
      const max = p.capacity * p.per
      s.tokens += p.refill * (tick - s.at)
      if (s.tokens > max) s.tokens = max
      s.at = tick
    } else {
      s.ticks = s.ticks.filter((x) => x > tick - p.span)
    }
    return s
  }
  const out = []
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, ps] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let denied = null
    if (best !== null) {
      const ps = routes.get(best)
      const ss = ps.map((p) => stateOf(p, key, tick))
      for (let i = 0; i < ps.length && denied === null; i++) {
        const p = ps[i]
        const ok = p.kind === 'bucket' ? ss[i].tokens >= p.per : BigInt(ss[i].ticks.length) < p.limit
        if (!ok) denied = p.name
      }
      if (denied === null) {
        ps.forEach((p, i) => {
          if (p.kind === 'bucket') ss[i].tokens -= p.per
          else ss[i].ticks.push(tick)
        })
      }
    }
    out.push({ tick, key, denied })
  }
  return out
}

let input = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', (c) => (input += c))
process.stdin.on('end', () => {
  let res
  try {
    res = run(parse(input))
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  let text = ''
  if (mode === 'replay') {
    for (const r of res) text += `${r.tick} ${r.key} ${r.denied === null ? 'allow' : 'deny ' + r.denied}\n`
  } else {
    const per = new Map()
    let a = 0, d = 0
    for (const r of res) {
      const c = per.get(r.key) || { a: 0, d: 0 }
      if (r.denied === null) (c.a++, a++)
      else (c.d++, d++)
      per.set(r.key, c)
    }
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      text += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
    }
    text += `total allowed=${a} denied=${d}\n`
  }
  process.stdout.write(text)
})
